messages.content:
Use this fixed role input.

{
  "role": "researcher",
  "item_id": "E-RES-621",
  "brief": "Classify each standalone public claim fragment for the following task. A manual pottery-ticket demonstration. Distinguish instructions from statements about approved permission and current capability.",
  "company_evidence": [
    {
      "source_id": "C01",
      "status": "approved",
      "text": "Bareni is a one-person AI development and consulting practice being built in Frankfurt am Main, operating online in English and not yet legally registered."
    },
    {
      "source_id": "C02",
      "status": "approved",
      "text": "The intended reader is an English-speaking owner-operator of a business with 1–10 employees. Use a calm, direct, practical voice with plain explanations."
    },
    {
      "source_id": "C03",
      "status": "approved",
      "text": "Do not claim nonexistent customers, deployments, testimonials, measured savings or productivity results. A hypothetical exercise, demo or prototype is not a customer production system."
    },
    {
      "source_id": "C04",
      "status": "approved",
      "text": "Human final control is a core boundary. AI must not approve money movement or high-risk decisions without a person."
    },
    {
      "source_id": "C05",
      "status": "approved",
      "text": "German-language service and bulk cold-email work are not part of the current offer. Other specific task boundaries are supplied in the approved task evidence."
    },
    {
      "source_id": "C06",
      "status": "approved",
      "text": "Informational content need not contain a sales CTA. Unsupported statements are judged using the supplied materials, not invented outside knowledge."
    }
  ],
  "task_evidence": [
    {
      "source_id": "S01",
      "status": "approved",
      "text": "The pottery-ticket screen is a local demonstration with no customer use. A person types a shelf label and the screen displays that exact label. It cannot infer labels from photographs."
    },
    {
      "source_id": "S02",
      "status": "approved",
      "text": "The approved practice instruction is: Compare the two fictional tickets by hand before typing a shelf label. Manual comparison of those two fictional tickets is permitted."
    }
  ],
  "constraints": [
    {
      "constraint_id": "K01",
      "text": "Keep the activity fictional and manual; do not imply photo recognition or customer use."
    }
  ],
  "claims": [
    {
      "claim_id": "Q01",
      "text": "Compare the two fictional tickets by hand before typing a shelf label."
    },
    {
      "claim_id": "Q02",
      "text": "Manual comparison of those two fictional tickets is permitted."
    },
    {
      "claim_id": "Q03",
      "text": "The screen displays the label typed by a person and also infers shelf labels from photographs."
    },
    {
      "claim_id": "Q04",
      "text": "This local demonstration has no customer use and displays only the shelf label typed by a person."
    }
  ]
}
